(function(){'use strict';
var STATE='welog-pair-sheet-v4',FONT='welog-font-lock-v1';
var sheet=document.getElementById('sheet'),controls=document.getElementById('controls'),previewBtn=document.getElementById('previewBtn'),saveBtn=document.getElementById('printBtn');
if(!sheet||!controls)return;
function read(){try{return JSON.parse(localStorage.getItem(STATE)||'{}')||{}}catch(e){return{}}}
function norm(v){if(/^KoPub Dotum/.test(v||''))return'KoPub Dotum Medium';if(/^KoPub Batang/.test(v||''))return'KoPub Batang Medium';if(!v||v==='__default__')return'Pretendard';return v}
var stacks={'Pretendard':'"WeLogMasterPretendard",sans-serif','Noto Sans KR':'"WeLogMasterNoto",sans-serif','KoPub Dotum Medium':'"WeLogMasterDotum",sans-serif','KoPub Batang Medium':'"WeLogMasterBatang",serif'};
function currentFont(){return norm(localStorage.getItem(FONT)||read().font||'Pretendard')}
function persistFont(v){v=norm(v);localStorage.setItem(FONT,v);var s=read();s.font=v;try{localStorage.setItem(STATE,JSON.stringify(s))}catch(e){}return v}
function applyFont(root){if(!root)return;var f=stacks[currentFont()]||stacks.Pretendard;root.style.setProperty('--welog-sheet-font',f,'important');root.style.setProperty('font-family',f,'important');root.querySelectorAll('*').forEach(function(el){el.style.setProperty('font-family',f,'important')})}
function syncFontSelect(){var sel=controls.querySelector('select[data-path="font"]');if(!sel)return;var want=currentFont();for(var i=0;i<sel.options.length;i++){if(norm(sel.options[i].value)===want){sel.selectedIndex=i;break}}}
function sync(){applyFont(sheet);syncFontSelect()}
controls.addEventListener('change',function(e){if(e.target.matches('select[data-path="font"]')){persistFont(e.target.value);setTimeout(sync,0);setTimeout(sync,120)}},true);
controls.addEventListener('input',function(e){if(e.target.matches('select[data-path="font"]')){persistFont(e.target.value);setTimeout(sync,0)}},true);
/* Repaint after tabs/controls cause the base app to replace sheet children. Observe only direct child replacement to avoid loops. */
new MutationObserver(function(){requestAnimationFrame(sync)}).observe(sheet,{childList:true,subtree:false});
document.addEventListener('click',function(e){if(e.target.closest('#tabs,.controls'))setTimeout(sync,80)},true);
window.addEventListener('pageshow',sync);document.addEventListener('visibilitychange',function(){if(!document.hidden)sync()});
/* Sticker upload bridge. Some browsers only fire change for file inputs; the base app listens on input. */
controls.addEventListener('change',function(e){var f=e.target;if(!f.matches('input[data-sticker-upload][type=file]')||!f.files||!f.files[0])return;setTimeout(function(){if(f.files&&f.files[0])f.dispatchEvent(new Event('input',{bubbles:true}))},0)},true);
/* Build preview from the current live DOM only. No re-layout/re-render. */
function ensurePreview(){var m=document.querySelector('.welog-live-preview');if(m)return m;m=document.createElement('div');m.className='welog-live-preview';m.hidden=true;m.innerHTML='<button class="welog-live-preview-bg" type="button"></button><section><header><b>저장 미리보기</b><button type="button" data-close>×</button></header><div class="welog-live-preview-vp"><div class="welog-live-preview-holder"></div></div></section>';document.body.appendChild(m);m.querySelector('.welog-live-preview-bg').onclick=function(){m.hidden=true};m.querySelector('[data-close]').onclick=function(){m.hidden=true};return m}
function liveClone(cls){sync();var c=sheet.cloneNode(true);c.id='';c.classList.add(cls);c.style.transform='none';c.style.margin='0';c.querySelectorAll('.welog-layout-overlay-fixed,.welog-align-guides,.welog-layout-box').forEach(function(x){x.remove()});applyFont(c);return c}
function openPreview(){var m=ensurePreview(),h=m.querySelector('.welog-live-preview-holder'),vp=m.querySelector('.welog-live-preview-vp');h.innerHTML='';var c=liveClone('welog-exact-preview-sheet');h.appendChild(c);m.hidden=false;requestAnimationFrame(function(){var w=c.scrollWidth||c.offsetWidth,hh=c.scrollHeight||c.offsetHeight,maxW=vp.clientWidth-48,maxH=vp.clientHeight-48,sc=Math.min(1,maxW/w,maxH/hh);c.style.transform='scale('+sc+')';c.style.transformOrigin='top left';h.style.width=(w*sc)+'px';h.style.height=(hh*sc)+'px'})}
async function saveExact(){if(!window.html2canvas)return alert('PNG 저장 기능을 불러오지 못했습니다.');sync();var old=saveBtn.textContent;saveBtn.disabled=true;saveBtn.textContent='저장 중…';var host=document.createElement('div');host.className='welog-final-export-host';var c=liveClone('welog-final-export-sheet');host.appendChild(c);document.body.appendChild(host);try{if(document.fonts&&document.fonts.ready)await document.fonts.ready;await new Promise(function(r){requestAnimationFrame(function(){requestAnimationFrame(r)})});var canvas=await html2canvas(c,{scale:2,useCORS:true,allowTaint:false,backgroundColor:'#fff',logging:false,imageTimeout:30000,width:c.scrollWidth,height:c.scrollHeight});var blob=await new Promise(function(resolve){canvas.toBlob(resolve,'image/png')});if(!blob)throw new Error('PNG blob failed');var a=document.createElement('a'),u=URL.createObjectURL(blob);a.href=u;a.download=((read().pairName||'WeLog').trim()||'WeLog')+'.png';document.body.appendChild(a);a.click();a.remove();setTimeout(function(){URL.revokeObjectURL(u)},3000)}catch(err){console.error(err);alert('PNG 저장에 실패했습니다.')}finally{host.remove();saveBtn.disabled=false;saveBtn.textContent=old}}
if(previewBtn)previewBtn.addEventListener('click',function(e){e.preventDefault();e.stopImmediatePropagation();openPreview()},true);
if(saveBtn)saveBtn.addEventListener('click',function(e){e.preventDefault();e.stopImmediatePropagation();saveExact()},true);
/* Preview/export shell. */
var css=document.createElement('style');css.textContent='.welog-live-preview[hidden]{display:none!important}.welog-live-preview{position:fixed;inset:0;z-index:99999;display:grid;place-items:center;padding:24px}.welog-live-preview-bg{position:absolute;inset:0;border:0;background:rgba(39,33,27,.48);backdrop-filter:blur(3px)}.welog-live-preview>section{position:relative;width:min(94vw,1400px);height:min(92vh,1000px);background:#f4f0e9;border-radius:16px;overflow:hidden;box-shadow:0 30px 90px #0004}.welog-live-preview header{height:54px;padding:0 18px;display:flex;align-items:center;justify-content:space-between;background:#fffdf9;border-bottom:1px solid #ddd5ca}.welog-live-preview header button{border:0;background:transparent;font-size:25px}.welog-live-preview-vp{height:calc(100% - 54px);overflow:auto;display:grid;place-items:center;padding:24px;box-sizing:border-box}.welog-live-preview-holder{position:relative}.welog-final-export-host{position:fixed;left:-100000px;top:0;z-index:-1;background:#fff}.welog-final-export-sheet{transform:none!important;transform-origin:top left!important}';document.head.appendChild(css);
sync();setTimeout(sync,200);
})();